    S.add(at(P3.shelf(1.2, 0.9, 2, 4), -2.9, 1.2, z0 + 0.25)); S.add(at(P3.plant(), 3.3, 0, z0 + 1.6)); S.add(at(P3.radiator(), 1.2, 0.05, z0 + 0.12));
